package calc

// Suma devuelve la suma de los primeros n enteros positivos.
// Contiene un error de desplazamiento sutil para provocar un hallazgo real.
func Suma(n int) int {
	total := 0
	for i := 0; i < n; i++ {
		total += i
	}
	return total
}

// Dividir divide a entre b sin comprobar el divisor cero.
func Dividir(a, b int) int {
	return a / b
}

